mapper.select:
SELECT stl.ACT_ORDER_ID AS orderid , stl.PORTFOLIO_ID AS portid, ptl.PORTFOLIO_NAME AS portname, stl.IS_NEED_SEND AS send , stl.SETTLE_DATE AS sdate , stl.SETTLE_AMT AS amt , stl.CCY AS ccy, pay.ACCT_NO AS payno , pay.ACCT_NAME AS payname , gat.ACCT_NO AS gatno , gat.ACCT_NAME AS gatname , gat.LARGE_PAYNO AS gatpayno , INF.SEND_STATUS AS status, stl.PURPOSE AS purpose, stl.REMARK AS remark FROM STL_ACT_ORDER stl left join PTL_PORTFOLIO ptl on ptl.PORTFOLIO_ID=stl.PORTFOLIO_ID left join STL_CAPACCT_INFO pay on (stl.ps = '02' and stl.MY_ACCT_NO = pay.ACCT_NO) or (stl.ps = '01' and stl.COUNTER_ACCT_NO = pay.ACCT_NO) left join STL_CAPACCT_INFO gat on (stl.ps = '01' and stl.MY_ACCT_NO = gat.ACCT_NO) or (stl.ps = '02' and stl.COUNTER_ACCT_NO = gat.ACCT_NO) left join INF_PAY_ORDERS_STATUS inf on inf.ORDER_ID = stl.ACT_ORDER_ID
stl.ORDER_STATUS = '01' and stl.COMMON_BUSI_TYPE = #{commonBusiType,jdbcType=VARCHAR}
and (stl.PORTFOLIO_ID in
null) OR stl.PORTFOLIO_ID in (
#{item} )
and stl.SETTLE_DATE = TO_DATE(#{sdate}, 'yyyy-MM-dd')
and stl.ACT_ORDER_ID = #{orderid}
and INF.SEND_STATUS = #{status}
